using Mbb.Archive.Modules.Retention.Application;
using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.BuildingBlocks.Domain;using Mbb.Archive.Modules.Retention.Application.Abstractions;using Mbb.Archive.Modules.Retention.Contracts.IntegrationEvents;namespace Mbb.Archive.Modules.Retention.Application.Holds.Release;public sealed class ReleaseLegalHoldCommandHandler:ICommandHandler<ReleaseLegalHoldCommand>{private readonly IRetentionRepository _repo;private readonly IOutbox<RetentionBoundary> _outbox;private readonly IUnitOfWork<RetentionBoundary> _uow;private readonly TimeProvider _time;public ReleaseLegalHoldCommandHandler(IRetentionRepository repo,IOutbox<RetentionBoundary> outbox,IUnitOfWork<RetentionBoundary> uow,TimeProvider time){_repo=repo;_outbox=outbox;_uow=uow;_time=time;}public async Task<Result> Handle(ReleaseLegalHoldCommand c,CancellationToken ct){var item=await _repo.GetCaseAsync(c.RetentionCaseId,ct);if(item is null)return Result.Failure(Error.NotFound("retention.case_not_found","Retention case was not found."));var hold=await _repo.GetActiveHoldAsync(item.Id,ct);if(hold is null)return Result.Failure(Error.NotFound("retention.hold_not_found","Active legal hold was not found."));try{var now=_time.GetUtcNow();hold.Release(now);item.ReleaseHold();_outbox.Enqueue(new LegalHoldReleasedIntegrationEvent(Guid.CreateVersion7(),item.Id,item.ArchiveRecordId,now));await _uow.SaveChangesAsync(ct);return Result.Success();}catch(DomainRuleViolationException ex){return Result.Failure(Error.Conflict("retention.hold_conflict",ex.Message));}}}
